export function transform(input, lib) {
  if (typeof input !== "string") throw new Error("input must be a string");
  const lines = input.split(/\r?\n/);
  let i = 0;
  while (i < lines.length && lines[i].trim() === "") i++;
  const h = /^Mach Virtual Memory Statistics: \(page size of (\d+) bytes\)\s*$/.exec(lines[i] || "");
  if (!h) throw new Error("invalid header");
  const pageSize = BigInt(h[1]);
  if (pageSize <= 0n) throw new Error("invalid page size");
  const stats = new Map();
  for (const raw of lines.slice(i + 1)) {
    if (raw.trim() === "") continue;
    const m = /^(.*?):\s*(\d+)\.\s*$/.exec(raw);
    if (!m) throw new Error("malformed line: " + raw);
    stats.set(m[1].trim(), BigInt(m[2]));
  }
  const map = [
    ["Pages free", "memory.free_bytes"],
    ["Pages active", "memory.active_bytes"],
    ["Pages inactive", "memory.inactive_bytes"],
    ["Pages speculative", "memory.speculative_bytes"],
    ["Pages wired down", "memory.wired_bytes"],
    ["Pages occupied by compressor", "memory.compressor_bytes"],
  ];
  let out = "";
  for (const [label, metric] of map) {
    if (!stats.has(label)) throw new Error("missing statistic: " + label);
    out += `{"metric":"${metric}","value":${(stats.get(label) * pageSize).toString()}}\n`;
  }
  return out;
}
